static void check_authmethod_valid ( const char * authmethod , const char * const * valid_methods , const char * conntype ) { const char * const * p ; for ( p = valid_methods ; * p ; p ++ ) { if ( strchr ( authmethod , ' ' ) ) { if ( strncmp ( authmethod , * p , ( authmethod - strchr ( authmethod , ' ' ) ) ) == 0 ) { return ; } } } pg_fatal ( "invalid authentication method \"%s\" for \"%s\" connections" , authmethod , conntype ) ; } 